'use client';
import {useEffect,useRef,useState} from 'react';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {readUnifiedPostingReceipt} from '@/lib/financial-unified-posting';
import {validateUnifiedSaveRequest,type UnifiedSaveRequest} from '@/lib/financial-unified-save';
type Pending={id:string;reconciliation:UnifiedSaveRequest};
type Props={saved:UnifiedSaveRequest;onCompleted:()=>void;onCancelled?:()=>void;onRecoveryLock?:(locked:boolean)=>void};
export function FinancialUnifiedPosting(props:Props){const s=props.saved;return <Posting key={[s.scope.tenant,s.scope.property,s.scope.actor,s.batch].join(':')} {...props}/>}
function Posting({saved,onCompleted,onCancelled,onRecoveryLock}:Props){
 const {scope,batch}=saved,key=['irp.unified.post.v1',scope.tenant,scope.property,scope.actor,batch].join(':');
 const [pending,setPending]=useState<Pending|null>(null),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[done,setDone]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),locked=useRef(false);
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const p=JSON.parse(raw) as Pending;validateUnifiedSaveRequest(p.reconciliation);const s=p.reconciliation;if(!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(p.id)||s.scope.tenant!==scope.tenant||s.scope.property!==scope.property||s.scope.actor!==scope.actor||s.batch!==batch)throw Error('Saved posting belongs to another workspace.');setPending(p)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to restore posting.')}return()=>{alive.current=false}},[key]);
 useEffect(()=>{onRecoveryLock?.(!ready||busy||!!pending)},[ready,busy,pending,onRecoveryLock]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen migration.');}
 async function run(kind:'post'|'check'|'cancel'){
  if(!ready||locked.current||done)return;locked.current=true;setBusy(true);setError('');setMessage('');
  try{await identify();let request=pending;if(!request){if(kind!=='post'||!confirmed)throw Error('Confirm the combined balances.');validateUnifiedSaveRequest(saved);if(sessionStorage.getItem(key))throw Error('Recover the existing posting first.');request={id:crypto.randomUUID(),reconciliation:structuredClone(saved)};sessionStorage.setItem(key,JSON.stringify(request));if(alive.current)setPending(request)}
   const args={p_tenant:scope.tenant,p_property:scope.property,p_request:request.id};let complete=false,cancelled=false;
   if(kind==='post'){if(!confirmed)throw Error('Confirm the combined balances.');readUnifiedPostingReceipt(await hotelRpc('commit_unified_financial_migration',{...args,p_unified_review:request.reconciliation.id,p_confirmed:true}),request.reconciliation,request.id);complete=true;}
   else{if(kind==='cancel'){if(!cancelConfirmed)throw Error('Confirm cancellation.');await hotelRpc('cancel_financial_migration_commit',{...args,p_batch:batch,p_confirmed:true})}const status=await hotelRpc<Record<string,unknown>>('financial_migration_commit_status',args);if(status.schema_version!==1||status.tenant_id!==scope.tenant||status.property_id!==scope.property||status.actor_id!==scope.actor||status.request_id!==request.id||typeof status.found!=='boolean'||typeof status.cancelled!=='boolean'||status.found&&status.cancelled||!status.found&&status.result!==null)throw Error('Posting status does not match this request.');if(status.found){readUnifiedPostingReceipt(status.result,request.reconciliation,request.id);complete=true}cancelled=status.cancelled;}
   await identify();if(alive.current){if(complete||cancelled){sessionStorage.removeItem(key);setPending(null);setDone(true);setMessage(complete?'Split migration posted.':'Split posting cancelled.');if(complete)onCompleted();else onCancelled?.()}else setMessage('No posting found. Retry or cancel the original request.');}
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to post combined migration.')}finally{locked.current=false;if(alive.current)setBusy(false)}
 }
 const displayed=pending?.reconciliation??saved;
 return <section className="card" aria-label="Post combined migration"><h3>Post combined migration</h3><p>Existing invoice and deposit matches preserve the recorded balances. Only additional balances receive new opening entries.</p><ul>{(displayed.review.allocations as {source_item_id:string;destination_kind:string;destination_id:string|null;amount_minor:string;evidence:string}[]).map(d=><li key={JSON.stringify([d.source_item_id,d.destination_id])}>{d.source_item_id} ({bankCloseMoney(d.amount_minor)}): {d.destination_id!==null?`Match existing record ${d.destination_id}`:'Create opening balance'} — {d.evidence}</li>)}</ul><label><input type="checkbox" checked={confirmed} disabled={!ready||busy||done} onChange={e=>setConfirmed(e.target.checked)}/>I confirm the combined source balances for cutover</label><button type="button" disabled={!ready||busy||done||!confirmed} onClick={()=>void run('post')}>{pending?'Retry combined posting':'Post combined migration'}</button>{pending&&<><button type="button" disabled={busy} onClick={()=>void run('check')}>Check combined posting</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel if migration was not posted</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel combined posting</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
